/**
 * The length of a month in a calendar.
 * Safety: `context` must be a live handle; `out_length` valid for a write.
 */
ts_status ts_calendar_month_length(const ts_context * context, uint16_t calendar, int32_t year, uint8_t month, uint8_t * out_length);

/**
 * Whether a year is a leap year in a calendar: `1` or `0`.
 * Safety: `context` must be a live handle; `out_leap` valid for a write.
 */
ts_status ts_calendar_is_leap(const ts_context * context, uint16_t calendar, int32_t year, uint8_t * out_leap);

/**
 * The weekday of a date as its ISO number: Monday is `1`, Sunday `7`.
 * Safety: `context` must be a live handle; `date` valid for a read; `out_weekday`
 * valid for a write.
 */
ts_status ts_calendar_weekday(const ts_context * context, const ts_calendar_date * date, uint8_t * out_weekday);

/**
 * The Julian day at the UTC midnight that begins a fixed day (fixed day
 * 1 is Monday, 1 January 1 CE; the relation is `fixed + 1721424.5`).
 */
double ts_calendar_jd_of_fixed(int64_t fixed);

/**
 * The fixed day a Julian day falls in, and, when `out_fraction` is not
 * null, the fraction of that day elapsed since its midnight.
 * Safety: `out_fraction` must be null or valid for a write.
 */
int64_t ts_calendar_fixed_of_jd(double jd, double * out_fraction);

/**
 * Resolves a civil date-time in a zone to a UTC instant under the
 * context's daylight-saving and unknown-time policies, with the metadata
 * a stored chart keeps. An unknown zone is `UNSUPPORTED` with the nearest
 * names as the hint; a civil time inside a gap under the `error` policy
 * is `INVALID_ARG` with the `DST_GAP` detail.
 * Safety: `context` must be a live handle; `civil` and `zone` valid for reads;
 * `out_resolution` valid for a read of its `struct_size` and a write.
 */
ts_status ts_time_resolve(const ts_context * context, const ts_civil_date_time * civil, const ts_zone_spec * zone, ts_zone_resolution * out_resolution);

/**
 * The civil date-time of a UTC instant in a zone, in a calendar, with
 * the resolution that applied.
 * Safety: `context` must be a live handle; `zone` valid for a read; `out_civil`
 * and `out_resolution` valid for reads of their `struct_size` and writes.
 */
ts_status ts_time_civil(const ts_context * context, double jd_utc, const ts_zone_spec * zone, uint16_t calendar, ts_civil_date_time * out_civil, ts_zone_resolution * out_resolution);

/**
 * Converts an instant between UT1, TT and UTC under the context's Delta T
 * model, reporting what was applied. A model that cannot answer for the
 * instant is `OUT_OF_RANGE`.
 * Safety: `context` must be a live handle; `out_conversion` valid for a read of
 * its `struct_size` and a write.
 */
ts_status ts_time_convert(const ts_context * context, double jd, uint32_t from, uint32_t to, ts_time_conversion * out_conversion);

/**
 * Delta T (TT less UT1) at a UT1 instant under the context's model, with
 * what produced it and its uncertainty where the source has one.
 * Safety: `context` must be a live handle; `out_delta_t` valid for a read of its
 * `struct_size` and a write.
 */
ts_status ts_time_delta_t(const ts_context * context, double jd_ut1, ts_delta_t * out_delta_t);

/**
 * Loads a `.tpack` or `.tbundle` file: a locale it brings is added, a
 * namespace it brings replaces what was loaded under the same keys. A
 * file that does not verify is `PACK`.
 * Safety: `context` must be a live handle; `bytes` valid for `bytes_len` reads;
 * `out_loaded` valid for a read of its `struct_size` and a write.
 */
ts_status ts_intl_load_pack(const ts_context * context, const uint8_t * bytes, size_t bytes_len, ts_intl_loaded * out_loaded);

/**
 * Selects the locale every render resolves from; an unknown one is
 * `UNSUPPORTED` naming the loaded locales.
 * Safety: `context` must be a live handle; `locale` a NUL-terminated string.
 */
ts_status ts_intl_set_locale(const ts_context * context, const char * locale);

/**
 * The locale every render resolves from, lent until the next call on the
 * context.
 * Safety: `context` must be a live handle; `out_locale` valid for a write.
 */
ts_status ts_intl_locale(const ts_context * context, ts_str * out_locale);

/**
 * Whether the current locale or its fallbacks have a message: `1` or `0`.
 * Safety: `context` must be a live handle; `key` a NUL-terminated string;
 * `out_has` valid for a write.
 */
ts_status ts_intl_has(const ts_context * context, const char * key, uint8_t * out_has);

/**
 * Renders a message with parameters given as a JSON object: a string, an
 * integer, a number or an array is itself; an entity is
 * `{"$entity": "graha.SUN"}`; a date `{"$date": {"calendar": "GREGORIAN",
 * "year": 2026, "month": 9, "day": 6}}`; a time `{"$time": {"hour": 6,
 * "minute": 15, "second": 0}}`; a date and time `{"$datetime": {"date":
 * {...}, "time": {...}}}`; a ghati count `{"$ghati": {"ghati": 12,
 * "pala": 30, "vipala": 0}}`. A null `params_json` renders with none.
 * The result blob carries the text, where it resolved from and the
 * warnings; a missing message renders as its key with a warning, never
 * an error.
 * The blob follows the `intl_render` schema of idl/api.json.
 * Safety: `context` must be a live handle; `key` a NUL-terminated string;
 * `params_json` null or one; `out_blob` valid for a write.
 */
ts_status ts_intl_render(const ts_context * context, const char * key, const char * params_json, ts_blob * out_blob);

/**
 * Positions over a grid of instants and bodies in the requested frame:
 * the provider answers in the frame it can, the SDK completes the rest
 * under the profile's override policy, and every step is stamped. A
 * context without an ephemeris is `CAPABILITY`; a provider failure is
 * `PROVIDER` with the provider's own code in the last error.
 * The blob follows the `positions` schema of idl/api.json.
 * Safety: `context` must be a live handle; `request` valid for a read, with its
 * instants and body ids valid for the counts it states; `out_blob` valid
 * for a write.
 */
ts_status ts_positions(const ts_context * context, const ts_position_request * request, ts_blob * out_blob);

